let m:integer = UInt(op2[1:0]);

if !(IsFeatureImplemented(FEAT_GICv3) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif m == 1 && NUM_GIC_PRIORITY_BITS < 6 then
    Undefined();
elsif (m == 2 || m == 3) && NUM_GIC_PRIORITY_BITS < 7 then
    Undefined();
elsif HaveEL(EL3) && !(EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() || PSTATE.EL == EL3) && EL3SDDUndefPriority() && SCR_EL3().FIQ == '1' then
    Undefined();
elsif PSTATE.EL == EL0 then
    Undefined();
elsif PSTATE.EL == EL1 then
    if ICC_SRE_EL1().SRE == '0' then
        AArch64_SystemAccessTrap(EL1, 0x18);
    elsif EL2Enabled() && ICH_HCR_EL2().TALL0 == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && HCR_EL2().FMO == '1' then
        X{64}(t) = ICV_AP0R_EL1(m);
    elsif HaveEL(EL3) && SCR_EL3().FIQ == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        X{64}(t) = ICC_AP0R_EL1(m);
    end;
elsif PSTATE.EL == EL2 then
    if ICC_SRE_EL2().SRE == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif HaveEL(EL3) && SCR_EL3().FIQ == '1' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        X{64}(t) = ICC_AP0R_EL1(m);
    end;
elsif PSTATE.EL == EL3 then
    if ICC_SRE_EL3().SRE == '0' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        X{64}(t) = ICC_AP0R_EL1(m);
    end;
end;

